import calendar
from datetime import date, timedelta

_WEEKDAYS = {
    "MO": 0,
    "TU": 1,
    "WE": 2,
    "TH": 3,
    "FR": 4,
    "SA": 5,
    "SU": 6,
}


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split(" ")
    kind = parts[0]
    k = int(parts[1])
    result: list[str] = []

    if kind == "DAILY":
        for i in range(count):
            result.append((start_date + timedelta(days=i * k)).isoformat())
        return result

    if kind == "WEEKLY":
        target_weekdays = sorted(_WEEKDAYS[code] for code in parts[2].split(","))
        week_monday = start_date - timedelta(days=start_date.weekday())
        step = timedelta(days=7 * k)
        while len(result) < count:
            for wd in target_weekdays:
                candidate = week_monday + timedelta(days=wd)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        break
            week_monday += step
        return result

    if kind == "MONTHLY":
        total_months = start_date.year * 12 + (start_date.month - 1)
        if len(parts) == 3:
            target_day = int(parts[2])
            while len(result) < count:
                year, month_zero = divmod(total_months, 12)
                month = month_zero + 1
                days_in_month = calendar.monthrange(year, month)[1]
                day = days_in_month if target_day == -1 else target_day
                if day <= days_in_month:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                total_months += k
        else:
            nth = int(parts[2])
            target_wd = _WEEKDAYS[parts[3]]
            while len(result) < count:
                year, month_zero = divmod(total_months, 12)
                month = month_zero + 1
                first_wd, days_in_month = calendar.monthrange(year, month)
                if nth == -1:
                    last_wd = (first_wd + days_in_month - 1) % 7
                    day = days_in_month - (last_wd - target_wd) % 7
                else:
                    first_occurrence = 1 + (target_wd - first_wd) % 7
                    day = first_occurrence + (nth - 1) * 7
                if day <= days_in_month:
                    candidate = date(year, month, day)
                    if candidate >= start_date:
                        result.append(candidate.isoformat())
                total_months += k
        return result

    if kind == "YEARLY":
        mm_str, dd_str = parts[2].split("-")
        month = int(mm_str)
        day = int(dd_str)
        year = start_date.year
        while len(result) < count:
            if day <= calendar.monthrange(year, month)[1]:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
            year += k
        return result

    raise ValueError(f"Unsupported rule: {rule}")
